    <script>
        async function getMessageData() {
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') {
                throw new Error('Chưa kết nối được dữ liệu tin nhắn. Hãy mở bảng trong ứng dụng chat.');
            }
            var messageId = await getCurrentMessageId();
            var chatMessages = await getChatMessages(messageId);
            if (!Array.isArray(chatMessages) || !chatMessages.length) return null;
            return typeof chatMessages[0].message === 'string' ? chatMessages[0].message : null;
        }

        // Song key: ưu tiên từ khóa tiếng Việt, nếu không có mới dùng từ khóa tiếng Trung.
        // Giá trị được ghi vào cả hai key để tương thích với các đoạn mã/phiên bản cũ.
        var BATTLE_KEY_ALIASES = [
            { vi: 'Bên Tấn Công', aliases: ['Phe công'], zh: '攻方' },
            { vi: 'Cảnh Giới Bên Tấn Công', aliases: ['Cảnh giới phe công'], zh: '攻方境界' },
            { vi: 'DC Bên Tấn Công', aliases: ['DC phe công'], zh: '攻方DC' },
            { vi: 'Bên Phòng Thủ', aliases: ['Phe thủ'], zh: '守方' },
            { vi: 'Cảnh Giới Bên Phòng Thủ', aliases: ['Cảnh giới phe thủ'], zh: '守方境界' },
            { vi: 'DC Bên Phòng Thủ', aliases: ['DC phe thủ'], zh: '守方DC' },
            { vi: 'Bậc Chênh Lệch', aliases: ['Bậc thang chênh lệch'], zh: '差值阶梯' },
            { vi: 'Luật Lệnh Thiên Đạo', aliases: ['Thiên đạo luật lệnh'], zh: '天道律令' },
            { vi: 'Nội Dung Luật Lệnh', zh: '律令内容' },
            { vi: 'Khởi Thừa Chuyển Hợp', zh: '起承转合' },
            { vi: 'Người Thắng Do Thiên Đạo Phán Định', aliases: ['Thiên đạo tài định bên thắng'], zh: '天道裁定胜者' },
            { vi: 'Phán Định Tự Kiểm', aliases: ['Tự tra phán định'], zh: '自查判定' },
            { vi: 'Cảnh Báo Kiểm Toán', zh: '审计警告' },
            { vi: 'Thiên Đạo Châm Biếm', aliases: ['Thiên đạo trào phúng'], zh: '天道嘲讽' },
            { vi: 'Mô Tả Giao Phong', aliases: ['Miêu tả giao phong'], zh: '交锋描述' }
        ];

        function escapeRegExp(text) {
            return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        }

        function readBattleField(content, viKey, zhKey, aliases) {
            // Thử mọi tên Việt trước khi fallback sang tên Trung.
            var keys = [viKey].concat(aliases || [], [zhKey]);
            for (var i = 0; i < keys.length; i++) {
                var match = content.match(new RegExp('\\[\\s*' + escapeRegExp(keys[i]) + '\\s*\\|([^\\]]+)\\]', 'i'));
                if (match && match[1].trim()) return match[1].trim();
            }
            return '';
        }

        function parseBattleData(messageText) {
            var result = {};
            if (typeof messageText !== 'string') return null;
            messageText = messageText.normalize('NFC');
            var blocks = Array.from(messageText.matchAll(/<battle_judge\s*>([\s\S]*?)<\/battle_judge\s*>/gi));
            var tagMatch = blocks.length ? blocks[blocks.length - 1] : null;
            if (!tagMatch || !tagMatch[1]) {
                return null;
            }
            var content = tagMatch[1];

            BATTLE_KEY_ALIASES.forEach(function(pair) {
                var value = readBattleField(content, pair.vi, pair.zh, pair.aliases);
                result[pair.vi] = value;
                result[pair.zh] = value;
            });
            return result;
        }

        function containsAny(text, words) {
            text = String(text || '').toLowerCase();
            return words.some(function(word) {
                return text.indexOf(String(word).toLowerCase()) !== -1;
            });
        }

        function resolveCharacterPortrait(name) {
            var targetWin = window;
            if (typeof parent !== 'undefined' && parent.window) {
                targetWin = parent.window;
            }

            try {
                if (typeof targetWin.getPortraitUrl === 'function') {
                    var url = targetWin.getPortraitUrl(name);
                    if (url) return url;
                }
            } catch(e) { console.warn(e); }

            try {
                if (targetWin.portraitPools) {
                    var activePool = 'default';
                    if (typeof targetWin.getActivePortraitPool === 'function') {
                        activePool = targetWin.getActivePortraitPool(name) || 'default';
                    }
                    var poolVal = targetWin.portraitPools[activePool] && targetWin.portraitPools[activePool][name];
                    if (poolVal) {
                        if (Array.isArray(poolVal) && poolVal.length > 0) return poolVal[0];
                        if (typeof poolVal === 'string') return poolVal;
                    }
                }
            } catch(e) { console.warn(e); }

            try {
                var storage = window.localStorage;
                if (storage) {
                    var imgCacheRaw = storage.getItem("daoyuan_images_cache_v2");
                    var prefRaw = storage.getItem("daoyuan_portrait_preferences_v2");

                    var imgCache = imgCacheRaw ? JSON.parse(imgCacheRaw) : null;
                    var pref = prefRaw ? JSON.parse(prefRaw) : null;

                    if (imgCache && imgCache.data && imgCache.data.entities) {
                        var entity = imgCache.data.entities[name];
                        if (entity && Array.isArray(entity.images) && entity.images.length > 0) {
                            var activeTheme = "default";
                            if (pref && pref.activeThemes && pref.activeThemes[name]) {
                                activeTheme = pref.activeThemes[name];
                            }

                            var matchedImages = entity.images.filter(function(img) {
                                return img.theme === activeTheme;
                            });

                            if (matchedImages.length === 0) {
                                matchedImages = entity.images.filter(function(img) {
                                    return img.theme === "default";
                                });
                            }

                            if (matchedImages.length > 0) {
                                var index = 0;
                                if (pref && pref.indices && pref.indices[name] && pref.indices[name][activeTheme] !== undefined) {
                                    index = parseInt(pref.indices[name][activeTheme]) % matchedImages.length;
                                }
                                if (isNaN(index)) index = 0;
                                return matchedImages[index].url || '';
                            }
                        }
                    }

                    if (pref && pref.customImages && pref.customImages[name]) {
                        var activeTheme = (pref.activeThemes && pref.activeThemes[name]) || "default";
                        var customUrls = pref.customImages[name][activeTheme];
                        if (Array.isArray(customUrls) && customUrls.length > 0) {
                            return customUrls[0];
                        }
                    }
                }
            } catch(e) {
                console.error(e);
            }

            return '';
        }

        function resolveCharacterPortraitsArrayLegacy(name) {
            var urls = [];
            var targetWin = window;
            if (typeof parent !== 'undefined' && parent.window) {
                targetWin = parent.window;
            }

            try {
                if (targetWin.portraitPools) {
                    var activePool = 'default';
                    if (typeof targetWin.getActivePortraitPool === 'function') {
                        activePool = targetWin.getActivePortraitPool(name) || 'default';
                    }
                    var poolVal = targetWin.portraitPools[activePool] && targetWin.portraitPools[activePool][name];
                    if (poolVal) {
                        if (Array.isArray(poolVal)) {
                            urls = poolVal.slice();
                        } else if (typeof poolVal === 'string') {
                            urls.push(poolVal);
                        }
                    }
                }
            } catch(e) {}

            try {
                var storage = window.localStorage;
                if (storage) {
                    var imgCacheRaw = storage.getItem("daoyuan_images_cache_v2");
                    var imgCache = imgCacheRaw ? JSON.parse(imgCacheRaw) : null;
                    if (imgCache && imgCache.data && imgCache.data.entities) {
                        var entity = imgCache.data.entities[name];
                        if (entity && Array.isArray(entity.images)) {
                            entity.images.forEach(function(img) {
                                if (img.url) urls.push(img.url);
                            });
                        }
                    }
                    var prefRaw = storage.getItem("daoyuan_portrait_preferences_v2");
                    var pref = prefRaw ? JSON.parse(prefRaw) : null;
                    if (pref && pref.customImages && pref.customImages[name]) {
                        var activeTheme = (pref.activeThemes && pref.activeThemes[name]) || "default";
                        var customUrls = pref.customImages[name][activeTheme];
                        if (Array.isArray(customUrls)) {
                            urls = urls.concat(customUrls);
                        }
                    }
                }
            } catch(e) {}

            if (urls.length === 0) {
                var fallback = resolveCharacterPortrait(name);
                if (fallback) urls.push(fallback);
            }

            return urls.filter(function(item, pos) {
                return urls.indexOf(item) === pos;
            });
        }


