                    // Phải tạo đúng kho như thanh trạng thái để không làm hỏng DB nếu mở trước.
                    req.onupgradeneeded = function() {
                        if (!req.result.objectStoreNames.contains('catalogs')) req.result.createObjectStore('catalogs');
                    };
                    req.onerror = function() { finish(null); };
                    req.onblocked = function() { finish(null); };
                    req.onsuccess = function() {
                        var db = req.result;
                        try {
                            var get = db.transaction('catalogs', 'readonly').objectStore('catalogs').get('last-successful-v1');
                            get.onsuccess = function() {
                                db.close();
                                var v = get.result;
                                finish(v && v.catalog && v.catalog.characters && typeof v.catalog.characters === 'object' ? v.catalog.characters : null);
                            };
                            get.onerror = function() { db.close(); finish(null); };
                        } catch (e) { try { db.close(); } catch (e2) {} finish(null); }
                    };
                } catch (e) { finish(null); }
            });
        }

        async function dyFetchRemoteCatalog() {
            var bases = [
                'https://raw.githubusercontent.com/YttriumCarbide/Daoyuan/main/',
                'https://cdn.jsdelivr.net/gh/YttriumCarbide/Daoyuan@main/'
            ];
            for (var i = 0; i < bases.length; i++) {
                try {
                    var ctrl = new AbortController();
                    var timer = setTimeout(function() { ctrl.abort(); }, 12000);
                    var res = await fetch(bases[i] + 'images.json', { signal: ctrl.signal, cache: 'no-store' });
                    clearTimeout(timer);
                    if (!res.ok) continue;
                    var json = await res.json();
                    var entities = json && json.schemaVersion === 2 && json.data && json.data.entities;
                    if (!entities) continue;
                    var out = {};
                    Object.keys(entities).forEach(function(key) {
                        var ent = entities[key];
                        if (!ent || ent.type !== 'character' || !Array.isArray(ent.images)) return;
                        ent.images.forEach(function(img) {
                            if (!img || typeof img.url !== 'string' || img.url.indexOf('https://') !== 0 || img.url.indexOf('|') !== -1) return;
                            var theme = (typeof img.theme === 'string' && img.theme) || 'default';
                            ((out[key] = out[key] || {})[theme] = out[key][theme] || []).push({ url: img.url });
                        });
                    });
                    if (Object.keys(out).length) return out;
                } catch (e) {}
            }
            return null;
        }

        async function dyLoadPortraitCatalog() {
            if (dyPortrait.loading || dyPortrait.ready) return;
            dyPortrait.loading = true;
            var chars = await dyReadIdbCatalog();
            if (!chars) chars = await dyFetchRemoteCatalog();
            dyPortrait.characters = chars || {};
            dyPortrait.index = {};
            Object.keys(dyPortrait.characters).forEach(function(key) {
                var n = dyNorm(key);
                if (n && !dyPortrait.index[n]) dyPortrait.index[n] = key;
            });
            dyPortrait.ready = true;
            dyPortrait.loading = false;
            if (chars) void refreshBattle(true);
        }

        function resolveCharacterPortraitsArray(name) {
            var urls = [];
            var raw = String(name || '').normalize('NFC').trim();
            if (!raw) return urls;
            var keys = [raw, raw.replace(/[·・]/g, '')];
            var norm = dyNorm(raw);

            var custom = dyReadStorage('daoyuan_custom_portraits', {});
            keys.forEach(function(k) {
                if (typeof custom[k] === 'string' && custom[k]) urls.push(custom[k]);
            });

            var mod = dyReadStorage('daoyuan_mod_portraits_v1', null);
            if (mod && mod.alias && mod.groups && mod.alias[norm] !== undefined && Array.isArray(mod.groups[mod.alias[norm]])) {
                urls = urls.concat(mod.groups[mod.alias[norm]]);
            }

            // Ảnh nhân vật MOD Phần Thiên Các 4.6.2 nhúng sẵn — vẫn hiện khi Thanh trạng thái chưa ghi localStorage
            if (Array.isArray(DY_PTC_PORTRAITS[norm])) urls = urls.concat(DY_PTC_PORTRAITS[norm]);

            var chars = dyPortrait.characters || {};
            var charKey = null;
            for (var i = 0; i < keys.length; i++) { if (chars[keys[i]]) { charKey = keys[i]; break; } }
            if (!charKey && dyPortrait.index[norm]) charKey = dyPortrait.index[norm];
            if (!charKey && mod && mod.zh && mod.zh[norm]) {
                charKey = chars[mod.zh[norm]] ? mod.zh[norm] : (dyPortrait.index[dyNorm(mod.zh[norm])] || null);
            }
            if (charKey) {
                var themes = chars[charKey];
                var pref = dyReadStorage('daoyuan_portrait_theme', {})[charKey];
                var order = [pref, 'default'].concat(Object.keys(themes));
                order.forEach(function(theme) {
                    if (theme && Array.isArray(themes[theme])) {
                        themes[theme].forEach(function(img) { if (img && img.url) urls.push(img.url); });
                    }
                });
            }

            if (urls.length === 0) urls = resolveCharacterPortraitsArrayLegacy(name);

            return urls.filter(function(item, pos) { return urls.indexOf(item) === pos; });
        }

        function dyEsc(text) {
