        function switchCardPortrait(role, dir) {
            var state = portraitState[role];
            if (!state.urls || state.urls.length <= 1) return;
            state.index = (state.index + dir + state.urls.length) % state.urls.length;

            var frame = document.getElementById('frame-' + role);
            if (frame) {
                frame.style.backgroundImage = "url('" + state.urls[state.index] + "')";
            }
            var text = document.getElementById('indicator-text-' + role);
            if (text) {
                text.innerText = (state.index + 1) + '/' + state.urls.length;
            }
        }

