        var viewerState = {
            active: false,
            scale: 1,
            posX: 0,
            posY: 0,
            isDragging: false,
            startX: 0,
            startY: 0,
            role: 'p1',
            urls: [],
            index: 0
        };

        var viewerModal = document.getElementById('portrait-viewer');
        var viewerWrapper = document.getElementById('viewer-wrapper');
        var viewerImg = document.getElementById('viewer-img');
        var viewerClose = document.getElementById('viewer-close');
        var viewerPrev = document.getElementById('viewer-prev');
        var viewerNext = document.getElementById('viewer-next');
        var viewerZoomTip = document.getElementById('viewer-zoom-tip');

        var charNamePlate = document.getElementById('viewer-char-name');
        var charRealmPlate = document.getElementById('viewer-char-realm');
        var charDcPlate = document.getElementById('viewer-char-dc');

        function openViewer(role) {
            var state = portraitState[role];
            if (!state.urls || state.urls.length === 0) return;

            viewerState.active = true;
            viewerState.role = role;
            viewerState.urls = state.urls;
            viewerState.index = state.index;
            viewerState.scale = 1;
            viewerState.posX = 0;
            viewerState.posY = 0;

            updateViewerImage();
            viewerModal.classList.add('active');

            document.body.style.overflow = 'hidden';
        }

        function closeViewer() {
            viewerState.active = false;
            viewerModal.classList.remove('active');
            document.body.style.overflow = '';
        }

        function updateViewerImage() {
            var currentUrl = viewerState.urls[viewerState.index];
            viewerImg.src = currentUrl;

            var state = portraitState[viewerState.role];
            charNamePlate.innerText = state.name;
            charRealmPlate.innerText = "Cảnh Giới: " + state.realm;
            charDcPlate.innerText = "Thiên Cơ DC: " + state.dc;

            resetTransform();

            if (viewerState.urls.length > 1) {
                viewerPrev.style.display = 'flex';
                viewerNext.style.display = 'flex';
            } else {
                viewerPrev.style.display = 'none';
                viewerNext.style.display = 'none';
            }
        }

        function resetTransform() {
            viewerState.scale = 1;
            viewerState.posX = 0;
            viewerState.posY = 0;
            applyTransform();
        }

        function applyTransform() {
            viewerWrapper.style.transform = 'translate(' + viewerState.posX + 'px, ' + viewerState.posY + 'px) scale(' + viewerState.scale + ')';
            viewerZoomTip.innerText = Math.round(viewerState.scale * 100) + '%';
            viewerZoomTip.style.opacity = '1';

            clearTimeout(viewerState.tipTimer);
            viewerState.tipTimer = setTimeout(function() {
                viewerZoomTip.style.opacity = '0';
            }, 2000);
        }

        viewerModal.addEventListener('wheel', function(e) {
            if (!viewerState.active) return;
            e.preventDefault();
            var zoomFactor = 0.1;
            if (e.deltaY < 0) {
                viewerState.scale = Math.min(5, viewerState.scale + zoomFactor);
            } else {
                viewerState.scale = Math.max(0.4, viewerState.scale - zoomFactor);
            }
            applyTransform();
        }, { passive: false });

        viewerWrapper.addEventListener('dblclick', function(e) {
            e.stopPropagation();
            if (viewerState.scale !== 1) {
                resetTransform();
            } else {
                viewerState.scale = 2.0;
                applyTransform();
            }
        });

        viewerWrapper.addEventListener('mousedown', function(e) {
            e.stopPropagation();
            viewerState.isDragging = true;
            viewerState.startX = e.clientX - viewerState.posX;
            viewerState.startY = e.clientY - viewerState.posY;
        });

        window.addEventListener('mousemove', function(e) {
            if (!viewerState.isDragging || !viewerState.active) return;
            viewerState.posX = e.clientX - viewerState.startX;
            viewerState.posY = e.clientY - viewerState.startY;
            applyTransform();
        });

        window.addEventListener('mouseup', function() {
            viewerState.isDragging = false;
        });

        var touchState = { lastDist: 0 };
        viewerWrapper.addEventListener('touchstart', function(e) {
            e.stopPropagation();
            if (e.touches.length === 1) {
                viewerState.isDragging = true;
                viewerState.startX = e.touches[0].clientX - viewerState.posX;
                viewerState.startY = e.touches[0].clientY - viewerState.posY;
            } else if (e.touches.length === 2) {
                viewerState.isDragging = false;
                touchState.lastDist = Math.hypot(
                    e.touches[0].clientX - e.touches[1].clientX,
                    e.touches[0].clientY - e.touches[1].clientY
                );
            }
        });

        window.addEventListener('touchmove', function(e) {
            if (!viewerState.active) return;
            if (e.touches.length === 1 && viewerState.isDragging) {
                viewerState.posX = e.touches[0].clientX - viewerState.startX;
                viewerState.posY = e.touches[0].clientY - viewerState.startY;
                applyTransform();
            } else if (e.touches.length === 2) {
                var dist = Math.hypot(
                    e.touches[0].clientX - e.touches[1].clientX,
                    e.touches[0].clientY - e.touches[1].clientY
                );
                var factor = dist / touchState.lastDist;
                viewerState.scale = Math.max(0.4, Math.min(5, viewerState.scale * factor));
                touchState.lastDist = dist;
                applyTransform();
            }
        });

        window.addEventListener('touchend', function() {
            viewerState.isDragging = false;
        });

        viewerPrev.addEventListener('click', function(e) {
            e.stopPropagation();
            if (viewerState.urls.length <= 1) return;
            viewerState.index = (viewerState.index - 1 + viewerState.urls.length) % viewerState.urls.length;
            updateViewerImage();
        });

        viewerNext.addEventListener('click', function(e) {
            e.stopPropagation();
            if (viewerState.urls.length <= 1) return;
            viewerState.index = (viewerState.index + 1) % viewerState.urls.length;
            updateViewerImage();
        });

        viewerClose.addEventListener('click', closeViewer);
        viewerModal.addEventListener('click', function(e) {
            if (e.target === viewerModal || e.target === document.getElementById('viewer-container')) {
                closeViewer();
            }
        });

        window.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && viewerState.active) {
                closeViewer();
            }
        });

        function setupFoldToggle() {
            var trigger = document.getElementById('panel-trigger');
            var body = document.getElementById('battle-main-body');
            var arrow = document.getElementById('fold-arrow');

            trigger.addEventListener('click', function() {
                if (body.style.display === 'none' || body.style.display === '') {
                    body.style.display = 'block';
                    arrow.classList.add('active');
                } else {
                    body.style.display = 'none';
                    arrow.classList.remove('active');
                }
            });
        }

        var refreshBusy = false;
        var refreshAgain = false;
        var lastBattleSnapshot = null;
        var refreshTimer = null;
        var panelStarted = false;
        var panelStopped = false;
        var portraitListeners = [];

        function showBattleStatus(text) {
            var body = document.getElementById('battle-main-body');
            body.innerHTML = '';
            var status = document.createElement('div');
            status.className = 'loading-text';
            status.textContent = text;
            body.appendChild(status);
        }

        async function refreshBattle(force) {
            if (panelStopped) return;
            if (refreshBusy) {
                refreshAgain = refreshAgain || !!force;
                return;
            }
            refreshBusy = true;
            try {
                var messageText = await getMessageData();
                if (panelStopped) return;
                var data = parseBattleData(messageText);
                if (!data) {
                    if (lastBattleSnapshot === null) {
                        showBattleStatus('Đang chờ khối <battle_judge> hoàn chỉnh trong tin nhắn…');
                    }
                    return;
                }
                var snapshot = JSON.stringify(data);
                if (force || snapshot !== lastBattleSnapshot) {
                    renderBattle(data);
                    lastBattleSnapshot = snapshot;
                }
            } catch (error) {
                if (lastBattleSnapshot === null && !panelStopped) {
                    showBattleStatus('Đang chờ dữ liệu: ' + error.message);
                }
            } finally {
                refreshBusy = false;
                if (refreshAgain && !panelStopped) {
                    refreshAgain = false;
                    void refreshBattle(true);
                }
            }
        }

        function init() {
            if (panelStarted) return;
            panelStarted = true;
            setupFoldToggle();
            var subtitles = ['Suy Diễn Thiên Cơ', 'Diễn Toán Thiên Cơ', 'Luân Chuyển Nhân Quả', 'Phán Quyết Đại Đạo'];
            document.getElementById('dynamic-sub').innerText = subtitles[Math.floor(Math.random() * subtitles.length)];
            void dyLoadPortraitCatalog();
            void refreshBattle(false);
            // Đọc lại đúng tin nhắn của bảng; hỗ trợ sửa tin và dữ liệu đến chậm.
            refreshTimer = setInterval(function() { void refreshBattle(false); }, 1000);
            var targets = [window];
            try { if (window.parent && window.parent !== window) targets.push(window.parent); } catch (e) {}
            targets.forEach(function(target) {
                ['daoyuan_portraits_changed', 'daoyuan_images_changed'].forEach(function(eventName) {
                    try {
                        var handler = function() { void refreshBattle(true); };
                        target.addEventListener(eventName, handler);
                        portraitListeners.push({ target: target, name: eventName, handler: handler });
                    } catch (e) {}
                });
            });
        }

        window.addEventListener('pagehide', function() {
            panelStopped = true;
            clearInterval(refreshTimer);
            portraitListeners.forEach(function(listener) {
                listener.target.removeEventListener(listener.name, listener.handler);
            });
            portraitListeners = [];
        });
        window.addEventListener('pageshow', function(event) {
            if (event.persisted) {
                panelStopped = false;
                panelStarted = false;
                // Toggle đã được gắn trước khi trang vào bộ nhớ đệm.
                void refreshBattle(true);
                refreshTimer = setInterval(function() { void refreshBattle(false); }, 1000);
            }
        });
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init, { once: true });
        } else {
            init();
        }
    </script>
</body>
</html>
